# Pipeline for analysis.R (generated by targetfy).
library(targets)
library(tarchetypes)

tar_source("R")
tar_option_set(packages = c("readr", "dplyr", "ggplot2"))

list(
  # Read and clean
  tar_file_read(
    sales_raw,
    "data/sales.csv",
    read = read_csv(!!.x, show_col_types = FALSE)
  ),
  tar_target(sales, clean_sales(sales_raw)),

  # Revenue by region
  tar_target(by_region, summarise_by_region(sales)),

  # Model
  tar_target(model, fit_revenue_model(sales)),
  tar_target(coefs, tidy_model(model)),

  # Outputs
  tar_target(revenue_plot, plot_revenue(by_region)),
  tar_file(revenue_png, save_plot(revenue_plot, "out/revenue.png")),
  tar_file(coefs_csv, save_coefs(coefs, "out/coefs.csv"))
)
